def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_prime_sequence(limit):
    prime_sequence = []
    num = 2
    while len(prime_sequence) < limit:
        if is_prime(num):
            prime_sequence.append(str(num))
        num += 1
    return ''.join(prime_sequence)

def solve(a, b):
    limit = a + b
    prime_sequence = generate_prime_sequence(limit)
    return prime_sequence[a:a + b]

