import math

def calculate_distance(p1, p2):
    """Calculate the Euclidean distance between two points."""
    return math.sqrt((p2[0] - p1[0]) ** 2 + (p2[1] - p1[1]) ** 2)

def format_distance(distance, precision):
    """Format the distance to the specified precision."""
    if precision > 0:
        return round(distance, precision)
    else:
        return round(distance)

def coordinates(p1, p2, precision=0):
    """Return the distance between two points on a cartesian plane."""
    distance = calculate_distance(p1, p2)
    return format_distance(distance, precision)

