def generate_chessboard_pattern(n, m):
    if n == 0 or m == 0:
        return ""

    pattern = []
    for i in range(n):
        row = []
        for j in range(m):
            if (i + j) % 2 == 0:
                row.append('*')
            else:
                row.append('.')
        pattern.append(''.join(row))

    return '\n'.join(pattern)

