    for i in range(len(seq1)):
        if start_index + i >= len(seq2):
            return False
        if not is_complementary(seq1[i], seq2[start_index + i]):
            return False
    return True

def check_DNA(seq1, seq2):
    """
    Check if two DNA sequences are fit to form a fully complementary DNA double helix.

    :param seq1: First DNA sequence
    :param seq2: Second DNA sequence
    :return: Boolean True if complementary, False otherwise
    """
    # Check if the sequences are of the same length
    if len(seq1) == len(seq2):
        return check_compatibility(seq1, seq2, 0)

    # Check if seq1 is a prefix of seq2
    if seq1 == seq2[:len(seq1)]:
        return check_compatibility(seq1, seq2, len(seq1))

    # Check if seq2 is a prefix of seq1
    if seq2 == seq1[:len(seq2)]:
        return check_compatibility(seq2, seq1, len(seq2))

    return False

