import math

def calculate_distance(x1, y1, x2, y2):
    """Calculate the Euclidean distance between two points."""
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def vector_length(vector):
    """Return the length of a 2D vector."""
    if len(vector) != 2:
        raise ValueError("Vector must have exactly two points")
    if len(vector[0]) != 2 or len(vector[1]) != 2:
        raise ValueError("Each point in the vector must have exactly two coordinates")
