    max_partitions = 0
    max_boxes = 0
    for partition in partitions:
        if len(partition) > max_boxes:
            max_boxes = len(partition)
            max_partitions = 1
        elif len(partition) == max_boxes:
            max_partitions += 1
    return max_partitions, max_boxes

