def calculate_monthly_loss(old_price, new_price, loss_rate):
    return old_price * (loss_rate / 100), new_price * (loss_rate / 100)

def calculate_remaining_amount(old_price, new_price, savings_per_month, loss_rate):
    months = 0
    while old_price > new_price:
        old_loss, new_loss = calculate_monthly_loss(old_price, new_price, loss_rate)
        old_price -= old_loss
        new_price -= new_loss
        months += 1
        if months % 2 == 0:
            loss_rate += 0.5
        old_price += savings_per_month
    return months, round(old_price - new_price)

