def find_cube_sums(n):
    cube_sums = {}
    for i in range(1, int(n**(1/3)) + 1):
        for j in range(i, int(n**(1/3)) + 1):
            cube_sum = i**3 + j**3
            if cube_sum > n:
                break
            if cube_sum in cube_sums:
                cube_sums[cube_sum].append((i, j))
            else:
                cube_sums[cube_sum] = [(i, j)]
    return cube_sums

