def find_cube_pairs(n):
    cube_dict = {}
    for i in range(1, int(n**(1/3)) + 1):
        cube = i ** 3
        if cube > n:
            break
        cube_dict[cube] = i
    pairs = []
    for a, b in cube_dict.items():
        for c in cube_dict:
            if c == a:
                continue
            d = n - a - c
            if d > 0 and d in cube_dict and cube_dict[d] != b:
                pairs.append((a, b, c, d))
    return pairs

def has_two_cube_sums(n):
    pairs = find_cube_pairs(n)
    return len(pairs) >= 2

