def build_breadth_first_order(arr, index=0):
    if index >= len(arr):
        return []
    left_child = find_left_child_index(index)
    right_child = find_right_child_index(index)
    return [arr[index]] + build_breadth_first_order(arr, left_child) + build_breadth_first_order(arr, right_child)

