def is_complete_binary_tree(arr):
    n = len(arr)
    if n == 0:
        return True
    last_non_leaf_index = (n - 2) // 2
    for i in range(last_non_leaf_index + 1):
        if find_left_child_index(i) < n and arr[find_left_child_index(i)] is None:
            return False
        if find_right_child_index(i) < n and arr[find_right_child_index(i)] is None:
            return False
    return True

def complete_binary_tree(a):
    if not is_complete_binary_tree(a):
        raise ValueError("The input array does not represent a complete binary tree.")

    n = len(a)
    bfs_order = [None] * n
    queue = [0]
    index = 0

    while queue:
        current_index = queue.pop(0)
        bfs_order[index] = a[current_index]
        index += 1

        left_child_index = find_left_child_index(current_index)
        right_child_index = find_right_child_index(current_index)

        if left_child_index < n:
            queue.append(left_child_index)
        if right_child_index < n:
            queue.append(right_child_index)

    return bfs_order

