def breadth_first_order(a):
    n = len(a)
    result = []
    queue = [0]  # Start with the root node index

    while queue:
        current_index = queue.pop(0)
        result.append(a[current_index])

        left_child_index = find_left_child_index(current_index)
        if left_child_index < n:
            queue.append(left_child_index)

        right_child_index = find_right_child_index(current_index)
        if right_child_index < n:
            queue.append(right_child_index)

    return result

def complete_binary_tree(a):
    return breadth_first_order(a)

