def find_nearest_multiple(n, m):
    lower_multiple = (n // m) * m
    upper_multiple = lower_multiple + m
    return lower_multiple, upper_multiple

def round_to_nearest_multiple(n, m):
    lower, upper = find_nearest_multiple(n, m)
    return n if n == lower or n == upper else min(lower, upper, key=lambda x: abs(n - x))

def rounding(n, m):
    return round_to_nearest_multiple(n, m)

